import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Slot } from "radix-ui";
import { cn } from "@/lib/utils";

// Generated by shadcn, restyled with the Lachmat tokens (no shadcn theme variables)
const buttonVariants = cva(
  "inline-flex shrink-0 items-center justify-center gap-2 whitespace-nowrap transition-colors select-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ink disabled:pointer-events-none disabled:opacity-40",
  {
    variants: {
      variant: {
        default: "bg-ink text-white hover:bg-ink/85",
        secondary: "bg-surface text-ink hover:bg-input",
        // darker gray, for buttons placed on a surface background (e.g. ProductCard)
        muted: "bg-muted-button text-ink hover:brightness-95",
        accent: "bg-lime text-ink hover:brightness-95",
        // for dark backgrounds, so the focus outline is white too
        inverse:
          "bg-white text-ink hover:bg-surface focus-visible:outline-white",
        link: "text-ink underline underline-offset-4 hover:text-ink/60",
        // plain text, like "Página anterior"
        ghost: "text-ink hover:text-ink/60",
      },
      size: {
        default: "px-5 py-3 type-footnote text-[18px]",
        sm: "px-4 py-2.5 type-subbutton",
        // footnote at its own 16px, for text-only buttons
        text: "type-footnote",
      },
    },
    compoundVariants: [
      // text-only variants have no box, so no padding
      { variant: ["link", "ghost"], className: "p-0" },
    ],
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

const Button = ({
  className,
  variant,
  size,
  asChild = false,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    // renders the child (e.g. a next/link) with the button styles
    asChild?: boolean;
  }) => {
  const Comp = asChild ? Slot.Root : "button";

  return (
    <Comp
      data-slot="button"
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  );
};

export { Button, buttonVariants };
